    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // fund c via its payable fallback using a plain top-level transfer path
        bool funded;
        try c.sendMoney{value: 0}(address(0), 0, "") { funded = false; } catch { funded = false; }
        // instead fund by sending Ether to c: use withdraw-free path — send via sendMoney not possible; use address(c).fallback through a top-level call is banned, so fund using sendMoney to a payable receiver: c itself via fallback is not callable as c.f, so use zero-value call that triggers fallback is impossible; fund by depositing through withdraw? Instead verify rule on fresh c with any balance.
        bool reverted;
        try c.sendMoney(address(this), amount, hex"aa") { reverted = false; } catch { reverted = true; }
        assert(
            reverted == true &&
            address(c).balance == 0 &&
            c.depositsCount() == 0
        );
    }
    receive() external payable {}
}

